		/** 
		 * Tests creating a new Security.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Security");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Security" );

			try {            
				Security entity = SecurityService.getSecurityInstance().createSecurity( generateNewEntity() );
				thePrimaryKey = entity.getSecurityId();
				LOGGER.info( "-- Successfully created a Security with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Security. 
		 */
		public Security testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Security" );

			Security entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Security with primary key" );
			msg.append( thePrimaryKey );
			
			SecurityFetchOneSummary fetchOneSummary = new SecurityFetchOneSummary( thePrimaryKey );

			try {
				entity = SecurityService.getSecurityInstance().getSecurity( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Security " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Security.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Security." );

			StringBuilder msg = new StringBuilder( "Failed to update a Security : " );        
			Security entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Security." );

				// for use later on...
				thePrimaryKey = entity.getSecurityId();

				SecurityService proxy = SecurityService.getSecurityInstance();            
				proxy.updateSecurity( entity );   

				LOGGER.info( "-- Successfully saved Security - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Security.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Security." );

			try{
			    Security entity = testRead(); 
				SecurityService.getSecurityInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Security with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Security with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Securitys.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Securitys:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Security : " );        
			List<Security> collection  = null;

			try {
				// call the static get method on the SecurityService
				collection = SecurityService.getSecurityInstance().getAllSecurity();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Security entity = null;            
					Iterator<Security> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getSecurityId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

